import React, { useEffect, useState } from 'react';
import { toast } from 'react-toastify';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiGrid,
  FiCheckCircle,
  FiXCircle,
  FiImage,
  FiHash,
  FiUploadCloud,
  FiX,
} from 'react-icons/fi';

import api from '../../services/api';
import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

import {
  useLanguage,
} from '../../contexts/LanguageContext';


const AdminServices = () => {

  // =====================================================
  // LANGUAGE
  // =====================================================

  const { t } = useLanguage();


  // =====================================================
  // STATE
  // =====================================================

  const [services, setServices] = useState([]);

  const [loading, setLoading] = useState(true);

  const [modalOpen, setModalOpen] = useState(false);

  const [editingService, setEditingService] =
    useState(null);

  const [submitting, setSubmitting] =
    useState(false);

  const [imagePreview, setImagePreview] =
    useState(null);

  const [imageRemoved, setImageRemoved] =
    useState(false);

  const [formData, setFormData] = useState({
    title: '',
    description: '',
    icon: '',
    image: null,
    is_active: true,
    order: 0,
  });


  // =====================================================
  // FETCH SERVICES
  // =====================================================

  useEffect(() => {

    fetchServices();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);


  const fetchServices = async () => {

    try {

      setLoading(true);

      const response = await api.get(
        '/api/services/all'
      );

      setServices(
        Array.isArray(response.data)
          ? response.data
          : []
      );

    } catch (error) {

      console.error(
        'Fetch services error:',
        error
      );

      toast.error(
        error.response?.data?.detail ||
          t('services.loadFailed')
      );

    } finally {

      setLoading(false);

    }

  };


  // =====================================================
  // RESET FORM
  // =====================================================

  const resetForm = () => {

    setEditingService(null);

    setFormData({
      title: '',
      description: '',
      icon: '',
      image: null,
      is_active: true,
      order: 0,
    });

    if (
      imagePreview &&
      imagePreview.startsWith('blob:')
    ) {
      URL.revokeObjectURL(imagePreview);
    }

    setImagePreview(null);

    setImageRemoved(false);

  };


  // =====================================================
  // OPEN ADD MODAL
  // =====================================================

  const handleAdd = () => {

    resetForm();

    setModalOpen(true);

  };


  // =====================================================
  // CLOSE MODAL
  // =====================================================

  const handleCloseModal = () => {

    setModalOpen(false);

    resetForm();

  };


  // =====================================================
  // IMAGE UPLOAD
  // =====================================================

  const handleImageChange = (e) => {

    const file =
      e.target.files?.[0];

    if (!file) {
      return;
    }


    const allowedTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
    ];


    if (
      !allowedTypes.includes(file.type)
    ) {

      toast.error(
        t('services.invalidImage')
      );

      e.target.value = '';

      return;

    }


    const maxSize =
      5 * 1024 * 1024;


    if (file.size > maxSize) {

      toast.error(
        t('services.imageTooLarge')
      );

      e.target.value = '';

      return;

    }


    if (
      imagePreview &&
      imagePreview.startsWith('blob:')
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setFormData((prev) => ({
      ...prev,
      image: file,
    }));


    const previewUrl =
      URL.createObjectURL(file);


    setImagePreview(
      previewUrl
    );

    setImageRemoved(false);

  };


  // =====================================================
  // REMOVE IMAGE
  // =====================================================

  const handleRemoveImage = () => {

    if (
      imagePreview &&
      imagePreview.startsWith('blob:')
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setFormData((prev) => ({
      ...prev,
      image: null,
    }));


    setImagePreview(null);

    setImageRemoved(true);

  };


  // =====================================================
  // SUBMIT CREATE / UPDATE
  // =====================================================

  const handleSubmit = async (e) => {

    e.preventDefault();


    if (
      !formData.title.trim()
    ) {

      toast.error(
        t('services.titleRequired')
      );

      return;

    }


    try {

      setSubmitting(true);


      const data =
        new FormData();


      data.append(
        'title',
        formData.title.trim()
      );


      data.append(
        'description',
        formData.description?.trim() ||
          ''
      );


      data.append(
        'icon',
        formData.icon?.trim() ||
          ''
      );


      data.append(
        'is_active',
        String(
          formData.is_active
        )
      );


      data.append(
        'order',
        String(
          formData.order || 0
        )
      );


      // =================================================
      // NEW IMAGE
      // =================================================

      if (
        formData.image instanceof File
      ) {

        data.append(
          'image',
          formData.image
        );

      }


      // =================================================
      // REMOVE EXISTING IMAGE
      // =================================================

      if (
        editingService &&
        imageRemoved &&
        !(
          formData.image instanceof File
        )
      ) {

        data.append(
          'remove_image',
          'true'
        );

      }


      // =================================================
      // UPDATE
      // =================================================

      if (editingService) {

        await api.put(
          `/api/services/${editingService.id}`,
          data
        );


        toast.success(
          t('services.updatedSuccess')
        );

      }


      // =================================================
      // CREATE
      // =================================================

      else {

        await api.post(
          '/api/services/',
          data
        );


        toast.success(
          t('services.createdSuccess')
        );

      }


      handleCloseModal();

      await fetchServices();

    } catch (error) {

      console.error(
        'Service operation error:',
        error
      );


      let message =
        t('services.operationFailed');


      const detail =
        error.response?.data?.detail;


      if (
        typeof detail === 'string'
      ) {

        message = detail;

      } else if (
        Array.isArray(detail)
      ) {

        message = detail
          .map(
            (item) =>
              item?.msg ||
              t('common.validationError')
          )
          .join(', ');

      }


      toast.error(message);

    } finally {

      setSubmitting(false);

    }

  };


  // =====================================================
  // EDIT
  // =====================================================

  const handleEdit = (service) => {

    setEditingService(
      service
    );


    setFormData({

      title:
        service.title || '',

      description:
        service.description || '',

      icon:
        service.icon || '',

      image: null,

      is_active:
        service.is_active !==
        undefined
          ? Boolean(
              service.is_active
            )
          : true,

      order:
        Number(service.order) ||
        0,

    });


    setImagePreview(
      service.image || null
    );


    setImageRemoved(false);

    setModalOpen(true);

  };


  // =====================================================
  // DELETE
  // =====================================================

  const handleDelete = async (id) => {

    const confirmed =
      window.confirm(
        t(
          'services.deleteConfirm'
        )
      );


    if (!confirmed) {
      return;
    }


    try {

      await api.delete(
        `/api/services/${id}`
      );


      toast.success(
        t('services.deletedSuccess')
      );


      await fetchServices();

    } catch (error) {

      console.error(
        'Delete service error:',
        error
      );


      toast.error(
        error.response?.data?.detail ||
          t('services.deleteFailed')
      );

    }

  };


  // =====================================================
  // SUMMARY
  // =====================================================

  const activeCount =
    services.filter(
      (service) =>
        service.is_active
    ).length;


  const inactiveCount =
    services.filter(
      (service) =>
        !service.is_active
    ).length;


  const imageCount =
    services.filter(
      (service) =>
        service.image
    ).length;


  // =====================================================
  // TABLE COLUMNS
  // =====================================================

  const columns = [

    {
      key: 'icon',

      label:
        t('services.icon'),

      render: (val) => (

        <div
          className="
            w-10
            h-10
            bg-blue-50
            rounded-lg
            flex
            items-center
            justify-center
            text-xl
            border
            border-blue-200
          "
        >
          {val || '📌'}
        </div>

      ),
    },


    {
      key: 'title',

      label:
        t('services.service'),

      render: (val, row) => (

        <div
          className="
            max-w-[220px]
          "
        >

          <p
            className="
              text-sm
              font-bold
              text-blue-900
              truncate
            "
          >
            {
              val ||
              t(
                'services.untitled'
              )
            }
          </p>


          {
            row.description && (

              <p
                className="
                  text-xs
                  text-blue-400
                  truncate
                  mt-1
                "
              >
                {
                  row.description
                }
              </p>

            )
          }

        </div>

      ),
    },


    {
      key: 'description',

      label:
        t('services.description'),

      render: (val) => (

        <p
          className="
            text-sm
            text-blue-500
            max-w-[280px]
            truncate
          "
        >
          {
            val ||
            t(
              'services.noDescription'
            )
          }
        </p>

      ),
    },


    {
      key: 'order',

      label:
        t('services.order'),

      render: (val) => (

        <div
          className="
            inline-flex
            items-center
            justify-center
            min-w-[36px]
            h-8
            px-2
            bg-blue-50
            text-blue-900
            rounded-lg
            text-xs
            font-bold
          "
        >
          {val ?? 0}
        </div>

      ),
    },


    {
      key: 'is_active',

      label:
        t('common.status'),

      render: (val) => (

        <span
          className={`
            inline-flex
            items-center
            gap-1.5
            px-2.5
            py-1.5
            rounded-full
            text-[11px]
            font-semibold

            ${
              val
                ? `
                  bg-blue-50
                  text-blue-700
                  border
                  border-blue-200
                `
                : `
                  bg-red-50
                  text-red-600
                  border
                  border-red-100
                `
            }
          `}
        >

          <span
            className={`
              w-1.5
              h-1.5
              rounded-full

              ${
                val
                  ? 'bg-blue-500'
                  : 'bg-red-500'
              }
            `}
          />


          {
            val
              ? t('common.active')
              : t('common.inactive')
          }

        </span>

      ),
    },


    {
      key: 'actions',

      label:
        t('common.actions'),

      render: (_, row) => (

        <div
          className="
            flex
            items-center
            gap-2
          "
        >

          <button
            type="button"

            onClick={() =>
              handleEdit(row)
            }

            className="
              w-8
              h-8
              flex
              items-center
              justify-center
              bg-blue-50
              text-blue-900
              rounded-lg
              hover:bg-blue-900
              hover:text-white
              transition
            "

            title={
              t(
                'services.editService'
              )
            }
          >
            <FiEdit2
              size={14}
            />
          </button>


          <button
            type="button"

            onClick={() =>
              handleDelete(
                row.id
              )
            }

            className="
              w-8
              h-8
              flex
              items-center
              justify-center
              bg-red-50
              text-red-600
              rounded-lg
              hover:bg-red-600
              hover:text-white
              transition
            "

            title={
              t(
                'services.deleteService'
              )
            }
          >
            <FiTrash2
              size={14}
            />
          </button>

        </div>

      ),
    },

  ];


  // =====================================================
  // RETURN
  // =====================================================

  return (

    <div className="w-full">


      {/* =================================================
          HEADER
      ================================================== */}

      <div
        className="
          flex
          flex-col
          sm:flex-row
          sm:items-center
          sm:justify-between
          gap-4
          mb-6
        "
      >

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-10
              h-10
              bg-blue-900
              text-white
              rounded-xl
              flex
              items-center
              justify-center
              shadow-sm
            "
          >
            <FiGrid
              size={18}
            />
          </div>


          <div>

            <h1
              className="
                text-xl
                md:text-2xl
                font-bold
                text-blue-900
              "
            >
              {t(
                'services.title'
              )}
            </h1>


            <p
              className="
                text-xs
                md:text-sm
                text-blue-400
                mt-1
              "
            >
              {t(
                'services.subtitle'
              )}
            </p>

          </div>

        </div>


        <button
          type="button"

          onClick={
            handleAdd
          }

          className="
            h-10
            px-4
            inline-flex
            items-center
            justify-center
            gap-2
            bg-red-600
            text-white
            rounded-lg
            text-sm
            font-semibold
            shadow-sm
            hover:bg-red-700
            hover:shadow-md
            transition-all
          "
        >
          <FiPlus
            size={17}
          />

          {t(
            'services.addService'
          )}
        </button>

      </div>


      {/* =================================================
          SUMMARY CARDS
      ================================================== */}

      <div
        className="
          grid
          grid-cols-2
          xl:grid-cols-4
          gap-3
          mb-6
        "
      >


        {/* TOTAL */}

        <div
          className="
            bg-white
            border
            border-blue-200
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {t(
                  'services.totalServices'
                )}
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-900
                  mt-1
                "
              >
                {services.length}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                bg-blue-50
                text-blue-900
                rounded-lg
                flex
                items-center
                justify-center
              "
            >
              <FiGrid
                size={18}
              />
            </div>

          </div>

        </div>


        {/* ACTIVE */}

        <div
          className="
            bg-white
            border
            border-blue-200
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {t(
                  'common.active'
                )}
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-600
                  mt-1
                "
              >
                {activeCount}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                bg-blue-50
                text-blue-600
                rounded-lg
                flex
                items-center
                justify-center
              "
            >
              <FiCheckCircle
                size={18}
              />
            </div>

          </div>

        </div>


        {/* INACTIVE */}

        <div
          className="
            bg-white
            border
            border-red-100
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {t(
                  'common.inactive'
                )}
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-red-600
                  mt-1
                "
              >
                {inactiveCount}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                bg-red-50
                text-red-600
                rounded-lg
                flex
                items-center
                justify-center
              "
            >
              <FiXCircle
                size={18}
              />
            </div>

          </div>

        </div>


        {/* IMAGES */}

        <div
          className="
            bg-white
            border
            border-blue-200
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {t(
                  'services.withImages'
                )}
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-red-600
                  mt-1
                "
              >
                {imageCount}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                bg-red-50
                text-red-600
                rounded-lg
                flex
                items-center
                justify-center
              "
            >
              <FiImage
                size={18}
              />
            </div>

          </div>

        </div>

      </div>


      {/* =================================================
          TABLE
      ================================================== */}

      <AdminCard
        className="
          border
          border-blue-200
          rounded-xl
          shadow-sm
          overflow-hidden
        "
      >

        <div
          className="
            px-5
            py-4
            border-b
            border-blue-200
          "
        >

          <h2
            className="
              text-sm
              font-bold
              text-blue-900
            "
          >
            {t(
              'services.allServices'
            )}
          </h2>


          <p
            className="
              text-xs
              text-blue-300
              mt-1
            "
          >
            {services.length}{' '}

            {
              services.length === 1
                ? t(
                    'services.service'
                  )
                : t(
                    'services.services'
                  )
            }{' '}

            {t(
              'services.found'
            )}
          </p>

        </div>


        <AdminTable
          columns={columns}
          data={services}
          loading={loading}
        />

      </AdminCard>


      {/* =================================================
          ADD / EDIT MODAL
      ================================================== */}

      <AdminModal
        isOpen={
          modalOpen
        }

        onClose={
          handleCloseModal
        }

        title={
          editingService
            ? t(
                'services.editService'
              )
            : t(
                'services.createService'
              )
        }
      >

        <form
          onSubmit={
            handleSubmit
          }
        >

          <div className="space-y-4">


            {/* ============================================
                TITLE
            ============================================ */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >
                {t(
                  'services.serviceTitle'
                )}

                <span
                  className="
                    text-red-600
                  "
                >
                  {' '}*
                </span>
              </label>


              <input
                type="text"

                value={
                  formData.title
                }

                onChange={(e) =>
                  setFormData(
                    (prev) => ({
                      ...prev,
                      title:
                        e.target.value,
                    })
                  )
                }

                placeholder={
                  t(
                    'services.titlePlaceholder'
                  )
                }

                className="
                  w-full
                  h-11
                  px-3.5
                  border
                  border-blue-200
                  rounded-lg
                  text-sm
                  text-blue-900
                  outline-none
                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10
                  transition
                "

                required
              />

            </div>


            {/* ============================================
                DESCRIPTION
            ============================================ */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >
                {t(
                  'services.description'
                )}
              </label>


              <textarea
                value={
                  formData.description
                }

                onChange={(e) =>
                  setFormData(
                    (prev) => ({
                      ...prev,

                      description:
                        e.target.value,
                    })
                  )
                }

                rows={4}

                placeholder={
                  t(
                    'services.descriptionPlaceholder'
                  )
                }

                className="
                  w-full
                  px-3.5
                  py-3
                  border
                  border-blue-200
                  rounded-lg
                  text-sm
                  text-blue-900
                  resize-none
                  outline-none
                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10
                  transition
                "
              />

            </div>


            {/* ============================================
                ICON + ORDER
            ============================================ */}

            <div
              className="
                grid
                grid-cols-1
                md:grid-cols-2
                gap-4
                w-full
                min-w-0
              "
            >


              {/* ICON */}

              <div className="min-w-0">

                <label
                  className="
                    block
                    text-sm
                    font-semibold
                    text-blue-900
                    mb-1.5
                  "
                >
                  {t(
                    'services.icon'
                  )}
                </label>


                <div
                  className="
                    relative
                    w-full
                    min-w-0
                  "
                >

                  <div
                    className="
                      absolute
                      left-1.5
                      top-1/2
                      -translate-y-1/2
                      w-8
                      h-8
                      bg-blue-50
                      rounded-md
                      flex
                      items-center
                      justify-center
                      text-lg
                      pointer-events-none
                    "
                  >
                    {
                      formData.icon ||
                      '📌'
                    }
                  </div>


                  <input
                    type="text"

                    value={
                      formData.icon
                    }

                    onChange={(e) =>
                      setFormData(
                        (prev) => ({
                          ...prev,

                          icon:
                            e.target.value,
                        })
                      )
                    }

                    placeholder="📚"

                    maxLength={10}

                    className="
                      block
                      w-full
                      min-w-0
                      h-11
                      pl-12
                      pr-3
                      border
                      border-blue-200
                      rounded-lg
                      text-sm
                      text-blue-900
                      bg-white
                      outline-none
                      overflow-hidden
                      text-ellipsis
                      whitespace-nowrap
                      focus:border-blue-900
                      focus:ring-2
                      focus:ring-blue-900/10
                    "
                  />

                </div>


                <p
                  className="
                    text-[10px]
                    text-blue-300
                    mt-1.5
                  "
                >
                  {t(
                    'services.iconExample'
                  )}
                </p>

              </div>


              {/* ORDER */}

              <div className="min-w-0">

                <label
                  className="
                    block
                    text-sm
                    font-semibold
                    text-blue-900
                    mb-1.5
                  "
                >
                  {t(
                    'services.displayOrder'
                  )}
                </label>


                <div className="relative">

                  <FiHash
                    className="
                      absolute
                      left-3.5
                      top-1/2
                      -translate-y-1/2
                      text-blue-300
                      pointer-events-none
                    "
                  />


                  <input
                    type="number"

                    min="0"

                    value={
                      formData.order
                    }

                    onChange={(e) =>
                      setFormData(
                        (prev) => ({
                          ...prev,

                          order:
                            Number(
                              e.target.value
                            ) || 0,
                        })
                      )
                    }

                    className="
                      w-full
                      h-11
                      pl-10
                      pr-3.5
                      border
                      border-blue-200
                      rounded-lg
                      text-sm
                      text-blue-900
                      outline-none
                      focus:border-blue-900
                      focus:ring-2
                      focus:ring-blue-900/10
                    "
                  />

                </div>


                <p
                  className="
                    text-[10px]
                    text-blue-300
                    mt-1.5
                  "
                >
                  {t(
                    'services.orderHelp'
                  )}
                </p>

              </div>

            </div>


            {/* ============================================
                IMAGE UPLOAD
            ============================================ */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >
                {t(
                  'services.serviceImage'
                )}
              </label>


              {
                !imagePreview ? (

                  <label
                    className="
                      w-full
                      min-h-[150px]
                      border-2
                      border-dashed
                      border-blue-200
                      rounded-xl
                      flex
                      flex-col
                      items-center
                      justify-center
                      cursor-pointer
                      bg-blue-50
                      hover:border-blue-400
                      transition-all
                    "
                  >

                    <div
                      className="
                        w-12
                        h-12
                        bg-blue-50
                        text-blue-900
                        rounded-xl
                        flex
                        items-center
                        justify-center
                        mb-3
                      "
                    >
                      <FiUploadCloud
                        size={24}
                      />
                    </div>


                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900
                      "
                    >
                      {t(
                        'services.uploadImage'
                      )}
                    </p>


                    <p
                      className="
                        text-xs
                        text-blue-300
                        mt-1
                      "
                    >
                      JPG, PNG or WEBP
                    </p>


                    <p
                      className="
                        text-[10px]
                        text-blue-300
                        mt-1
                      "
                    >
                      {t(
                        'services.maxFileSize'
                      )}
                    </p>


                    <input
                      type="file"

                      accept="
                        image/jpeg,
                        image/png,
                        image/webp
                      "

                      onChange={
                        handleImageChange
                      }

                      className="hidden"
                    />

                  </label>

                ) : (

                  <div
                    className="
                      relative
                      w-full
                      h-[220px]
                      bg-blue-50
                      rounded-xl
                      overflow-hidden
                      border
                      border-blue-200
                      group
                    "
                  >

                    <img
                      src={
                        imagePreview
                      }

                      alt={
                        t(
                          'services.imagePreview'
                        )
                      }

                      className="
                        w-full
                        h-full
                        object-cover
                      "
                    />


                    <div
                      className="
                        absolute
                        inset-0
                        bg-black/30
                        opacity-0
                        group-hover:opacity-100
                        transition
                      "
                    />


                    <label
                      className="
                        absolute
                        left-1/2
                        top-1/2
                        -translate-x-1/2
                        -translate-y-1/2
                        h-10
                        px-4
                        bg-white
                        text-blue-900
                        rounded-lg
                        text-sm
                        font-semibold
                        flex
                        items-center
                        justify-center
                        gap-2
                        cursor-pointer
                        opacity-0
                        group-hover:opacity-100
                        shadow
                        transition
                      "
                    >

                      <FiUploadCloud
                        size={16}
                      />


                      {t(
                        'services.changeImage'
                      )}


                      <input
                        type="file"

                        accept="
                          image/jpeg,
                          image/png,
                          image/webp
                        "

                        onChange={
                          handleImageChange
                        }

                        className="hidden"
                      />

                    </label>


                    <button
                      type="button"

                      onClick={
                        handleRemoveImage
                      }

                      className="
                        absolute
                        top-3
                        right-3
                        w-9
                        h-9
                        bg-red-600
                        text-white
                        rounded-lg
                        flex
                        items-center
                        justify-center
                        hover:bg-red-700
                        shadow
                        transition
                      "

                      title={
                        t(
                          'services.removeImage'
                        )
                      }
                    >
                      <FiX
                        size={18}
                      />
                    </button>

                  </div>

                )
              }

            </div>


            {/* ============================================
                ACTIVE STATUS
            ============================================ */}

            <label
              className={`
                flex
                items-center
                justify-between
                gap-3
                p-4
                border
                rounded-xl
                cursor-pointer
                transition-all

                ${
                  formData.is_active
                    ? `
                      border-blue-200
                      bg-blue-50/60
                    `
                    : `
                      border-blue-200
                      bg-white
                    `
                }
              `}
            >

              <div
                className="
                  flex
                  items-center
                  gap-3
                "
              >

                <div
                  className={`
                    w-9
                    h-9
                    rounded-lg
                    flex
                    items-center
                    justify-center

                    ${
                      formData.is_active
                        ? `
                          bg-blue-100
                          text-blue-600
                        `
                        : `
                          bg-blue-50
                          text-blue-300
                        `
                    }
                  `}
                >

                  {
                    formData.is_active ? (

                      <FiCheckCircle
                        size={17}
                      />

                    ) : (

                      <FiXCircle
                        size={17}
                      />

                    )
                  }

                </div>


                <div>

                  <p
                    className="
                      text-sm
                      font-semibold
                      text-blue-900
                    "
                  >
                    {t(
                      'services.activeService'
                    )}
                  </p>


                  <p
                    className="
                      text-[10px]
                      text-blue-300
                      mt-0.5
                    "
                  >
                    {t(
                      'services.showOnWebsite'
                    )}
                  </p>

                </div>

              </div>


              <div
                className={`
                  relative
                  w-11
                  h-6
                  rounded-full
                  transition

                  ${
                    formData.is_active
                      ? 'bg-blue-500'
                      : 'bg-blue-200'
                  }
                `}
              >

                <div
                  className={`
                    absolute
                    top-1
                    w-4
                    h-4
                    bg-white
                    rounded-full
                    shadow
                    transition-all

                    ${
                      formData.is_active
                        ? 'left-6'
                        : 'left-1'
                    }
                  `}
                />

              </div>


              <input
                type="checkbox"

                checked={
                  formData.is_active
                }

                onChange={(e) =>
                  setFormData(
                    (prev) => ({
                      ...prev,

                      is_active:
                        e.target.checked,
                    })
                  )
                }

                className="hidden"
              />

            </label>

          </div>


          {/* =================================================
              MODAL FOOTER
          ================================================== */}

          <div
            className="
              mt-6
              pt-4
              border-t
              border-blue-200
              flex
              items-center
              justify-end
              gap-3
            "
          >

            <button
              type="button"

              onClick={
                handleCloseModal
              }

              disabled={
                submitting
              }

              className="
                h-10
                px-4
                bg-white
                border
                border-blue-200
                text-blue-400
                rounded-lg
                text-sm
                font-semibold
                hover:bg-blue-50
                disabled:opacity-50
                disabled:cursor-not-allowed
                transition
              "
            >
              {t(
                'common.cancel'
              )}
            </button>


            <button
              type="submit"

              disabled={
                submitting
              }

              className="
                min-w-[130px]
                h-10
                px-5
                bg-red-600
                text-white
                rounded-lg
                text-sm
                font-semibold
                hover:bg-red-700
                disabled:opacity-50
                disabled:cursor-not-allowed
                transition
              "
            >

              {
                submitting
                  ? editingService
                    ? t(
                        'services.updating'
                      )
                    : t(
                        'services.creating'
                      )
                  : editingService
                  ? t(
                      'services.updateService'
                    )
                  : t(
                      'services.createService'
                    )
              }

            </button>

          </div>

        </form>

      </AdminModal>

    </div>

  );

};


export default AdminServices;
